import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.CmaAMB6e.js";const m=JSON.parse('{"title":"鸿蒙 (HarmonyOS) 开发环境搭建","description":"","frontmatter":{},"headers":[],"relativePath":"harmony/setup.md","filePath":"harmony/setup.md","lastUpdated":1784195062000}'),d={name:"harmony/setup.md"};function l(i,t,n,h,c,s){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="鸿蒙-harmonyos-开发环境搭建" tabindex="-1">鸿蒙 (HarmonyOS) 开发环境搭建 <a class="header-anchor" href="#鸿蒙-harmonyos-开发环境搭建" aria-label="Permalink to &quot;鸿蒙 (HarmonyOS) 开发环境搭建&quot;">​</a></h1><blockquote><p>目标：装好 DevEco Studio，跑通第一个 ArkTS 项目。约 1-2 小时。</p></blockquote><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>操作系统：macOS / Windows 均可</li><li>内存：建议 16GB+</li><li>需注册华为开发者账号（用于模拟器与真机调试）</li></ul><h2 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to &quot;安装步骤&quot;">​</a></h2><h3 id="_1-注册华为开发者账号" tabindex="-1">1. 注册华为开发者账号 <a class="header-anchor" href="#_1-注册华为开发者账号" aria-label="Permalink to &quot;1. 注册华为开发者账号&quot;">​</a></h3><p>到 <a href="https://developer.harmonyos.com/cn/" target="_blank" rel="noreferrer">developer.harmonyos.com</a> 注册并完成实名认证（个人即可）。</p><h3 id="_2-下载-deveco-studio" tabindex="-1">2. 下载 DevEco Studio <a class="header-anchor" href="#_2-下载-deveco-studio" aria-label="Permalink to &quot;2. 下载 DevEco Studio&quot;">​</a></h3><p>到官网下载页获取 DevEco Studio（基于 IntelliJ，体验类似 Android Studio）。</p><h3 id="_3-配置-sdk" tabindex="-1">3. 配置 SDK <a class="header-anchor" href="#_3-配置-sdk" aria-label="Permalink to &quot;3. 配置 SDK&quot;">​</a></h3><p>首次启动 DevEco Studio，向导会引导安装 HarmonyOS SDK（含 ArkTS、ArkUI 工具链）。</p><h3 id="_4-登录账号" tabindex="-1">4. 登录账号 <a class="header-anchor" href="#_4-登录账号" aria-label="Permalink to &quot;4. 登录账号&quot;">​</a></h3><p>DevEco 内登录华为开发者账号，否则无法使用模拟器与真机调试。</p><h2 id="创建第一个项目" tabindex="-1">创建第一个项目 <a class="header-anchor" href="#创建第一个项目" aria-label="Permalink to &quot;创建第一个项目&quot;">​</a></h2><ol><li>New Project → Empty Ability</li><li>填 Project Name、Bundle Name</li><li>等待 hvigor 同步完成</li></ol><h2 id="运行验证" tabindex="-1">运行验证 <a class="header-anchor" href="#运行验证" aria-label="Permalink to &quot;运行验证&quot;">​</a></h2><p>三种运行方式（按门槛递增）：</p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>适用</th></tr></thead><tbody><tr><td><strong>Previewer</strong></td><td>DevEco 内置预览，秒开</td><td>写 UI 时快速看效果（类比前端 HMR）</td></tr><tr><td><strong>模拟器</strong></td><td>本地/远程模拟器</td><td>完整功能验证</td></tr><tr><td><strong>真机</strong></td><td>USB 连华为手机</td><td>最终验证</td></tr></tbody></table><ul><li>开发 UI 阶段优先用 Previewer（最快）</li><li>点工具栏 Previewer 即可看到 <code>Text(&#39;Hello World&#39;)</code> 渲染结果</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决</th></tr></thead><tbody><tr><td>模拟器无法启动</td><td>确认已登录华为账号且实名认证</td></tr><tr><td>SDK 下载慢</td><td>DevEco 设置里配镜像源，或挂代理</td></tr><tr><td>ArkTS 语法报红</td><td>ArkTS 是 TS 子集，禁用 <code>any</code>、动态属性等，看官方语法约束文档</td></tr><tr><td>hvigor 同步失败</td><td>检查网络，确认 ohpm 源可达</td></tr><tr><td>真机调试需签名</td><td>用自动签名（DevEco 会引导）</td></tr></tbody></table><h2 id="前端类比锚点" tabindex="-1">前端类比锚点 <a class="header-anchor" href="#前端类比锚点" aria-label="Permalink to &quot;前端类比锚点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端</th><th>鸿蒙</th></tr></thead><tbody><tr><td>VS Code</td><td>DevEco Studio</td></tr><tr><td>npm/pnpm</td><td>ohpm</td></tr><tr><td>node_modules</td><td>oh_modules</td></tr><tr><td><code>npm run dev</code></td><td>Previewer / 点 Run</td></tr><tr><td>Chrome DevTools</td><td>DevEco Profiler + HiLog</td></tr><tr><td>React/Vue 组件</td><td>@Component struct + build()</td></tr><tr><td>Vite HMR</td><td>Previewer 实时预览</td></tr></tbody></table><h2 id="学习提示" tabindex="-1">学习提示 <a class="header-anchor" href="#学习提示" aria-label="Permalink to &quot;学习提示&quot;">​</a></h2><ul><li>ArkTS 语法对前端友好（接近 TypeScript），但<strong>不能完全当 TS 写</strong>，它有静态类型约束</li><li>官方文档和 API 更新较快，以 <a href="https://developer.harmonyos.com/cn/documentation" target="_blank" rel="noreferrer">developer.harmonyos.com</a> 为准</li><li>鸿蒙分 HarmonyOS（应用开发，本文档目标）与 OpenHarmony（开源底座），学习阶段以 HarmonyOS 为主</li></ul><p>完成环境搭建后，回到 <code>learning-path.md</code> 开始第一个概念。</p>',26)])])}const p=e(d,[["render",l]]);export{m as __pageData,p as default};
